228	int cmdarg_error(std::vector<std::string> args) {
229	    std::cout << "Incorrect argument: \n";
230	    for (int i = 0; i < args.size(); i++) {
231	        std::cout << "  " << args[i] << "\n";
232	    }
233	    cmdarg_help(1);
234	    exit(1);
235	}
