237	int cmdarg_help(int exit_id) {
238	    std::cout
239	        << "ventus-sim [--arg subarg1=val1,subarg2=val2,...]\n"
240	        << "\n"
241	        << "Supported cmdline arguments: \n"
242	        << "-f         FILE      string      // load cmd args from file\n"
243	        << "                                 // if no cmd args is given, -f ventus_args.txt is applied\n"
244	        << "\n"
245	        << "--task                           // create a new GPGPU task\n"
246	        << "  subarg:  name      string      // 任取\n"
247	        << "           id        uint        // 任取\n"
248	        << "\n"
249	        << "--kernel                         // create a new GPGPU kernel\n"
250	        << "  subarg:  name      string      // 任取\n"
251	        << "           metafile  string      // kernel的.metadata文件路径\n"
252	        << "           datafile  string      // kernel的.data文件路径\n"
253	        << "           taskid    uint        // 可选，若无则为不归属任何task的独立kernel。必须指向之前已经申明的task\n"
254	        << "\n"
255	        << "--dump-mem BEGIN,END uint,uint   // 仿真结束后打印指定的内存地址范围[BEGIN,END]，4字节对齐\n"
